def ref(doi):
 x=refs[doi.lower()];j=x['journalInfo'];return f"{x['authorString']} ({x['pubYear']}). {re.sub('<[^>]+>','',x['title']).rstrip('.')}. {j['journal']['title']} {j.get('volume','')}:{x.get('pageInfo','')}. https://doi.org/{x['doi']}"
def fig(key,num,short,cap):
 so=next(x for x in src if x['path']==f'figures/{key}_Fig{num}.png');doi=so['article_doi'];year=refs[doi.lower()]['pubYear'];return dict(path=so['path'],caption=f'{short} ({year}), Fig. {num}. {cap}',kind='article',source_url='https://doi.org/'+doi)
