 s=dict(title=plan['content_slides'][i]['title'],layout='figure-right',figure_width=5.49,body=ps,transcript=ps,cite=f'{shorts[i]} ({refs[doi]["pubYear"]})',refs=[ref(doi)],figure=fig(key,num,shorts[i],caps[i]));S.append(s)
